/**
 * The build-time view of the current desktop release: what the downloads CDN
 * said when the site was built. Generated by scripts/generate-desktop-release.mjs
 * into src/generated/ (gitignored) on every `yarn build` and `yarn dev`; this
 * module is the typed door the pages read it through, so nothing else imports
 * the JSON directly.
 *
 * Everything here is optional by design. The install links do not depend on
 * it -- they are version-free aliases from src/data/desktop-download.ts -- so
 * a build that could not reach the CDN still ships a correct page, minus the
 * version badge, the checksums link, and the sizes.
 */

import generated from '@/generated/desktop-release.json';
import type { DesktopArtifact } from './desktop-download';

export interface DesktopRelease {
  /** The stable tag the `latest` pointer named at build time ("v0.0.56"), or null when unreadable. */
  version: string | null;
  /** That release's checksums.txt, or null when the version is unknown. */
  checksumsUrl: string | null;
  /** Installer sizes in bytes, keyed by DesktopArtifact.key; absent when a HEAD failed. */
  artifacts: Partial<Record<DesktopArtifact['key'], { bytes: number }>>;
  generatedAt: string;
}

export const DESKTOP_RELEASE: DesktopRelease = generated as DesktopRelease;

/**
 * Bytes to the size a person expects next to a download button: decimal
 * megabytes, no decimals ("158 MB"), because that is what every OS's download
 * shelf shows and matching it is the honest choice.
 */
export const formatDownloadSize = (bytes: number): string => `${Math.round(bytes / 1_000_000)} MB`;
